const inputItems = $input.all();

function text(value) {
  return value === undefined || value === null ? '' : String(value);
}

function clean(value) {
  return text(value).trim();
}

function parseBatchItems(value) {
  if (value === undefined || value === null || value === '') return [];
  if (Array.isArray(value)) return value;
  if (typeof value === 'string') {
    const parsed = JSON.parse(value);
    if (!Array.isArray(parsed)) throw new Error('batchItems must be an array or JSON array string');
    return parsed;
  }
  throw new Error('batchItems must be an array or JSON array string');
}

function sanitizeFileName(value) {
  const fileName = clean(value)
    .replace(/[<>:"/\\|?*\x00-\x1F]/g, '_')
    .replace(/[. ]+$/g, '');
  if (!fileName) throw new Error('fileName is required');
  return fileName;
}

function cleanFolderPath(value) {
  const folderPath = clean(value).replace(/\\/g, '/').replace(/\/+$/g, '');
  if (!folderPath) throw new Error('folderPath is required');
  return folderPath;
}

function hasContent(job) {
  return Object.prototype.hasOwnProperty.call(job, 'contentText') && job.contentText !== undefined && job.contentText !== null;
}

function normalizeJob(raw, index) {
  const source = raw && typeof raw === 'object' ? raw : {};
  const fileUrl = clean(source.fileUrl || source.url || source.remoteUrl);
  const hasText = hasContent(source);
  if (!fileUrl && !hasText) {
    throw new Error(`Job ${index + 1}: fileUrl or contentText is required`);
  }

  const folderPath = cleanFolderPath(source.folderPath);
  const fileName = sanitizeFileName(source.fileName);
  const localPath = clean(source.localPath).replace(/\\/g, '/') || `${folderPath}/${fileName}`;
  const fileKind = clean(source.fileKind || (fileUrl ? 'image' : 'text')).toLowerCase() || (fileUrl ? 'image' : 'text');
  const mimeType = clean(source.mimeType || (fileUrl ? 'image/png' : 'text/plain; charset=utf-8'));

  return {
    ...source,
    fileUrl,
    contentText: hasText ? text(source.contentText) : '',
    folderPath,
    fileName,
    localPath,
    savedPath: localPath,
    sourceUrl: fileUrl,
    fileKind,
    mimeType,
  };
}

let concurrency = 8;
const jobs = [];

for (const item of inputItems) {
  const json = item.json || {};
  if (json.concurrency !== undefined && json.concurrency !== null && json.concurrency !== '') {
    const parsed = Number(json.concurrency);
    if (Number.isFinite(parsed)) concurrency = parsed;
  }

  const batchItems = parseBatchItems(json.batchItems);
  if (batchItems.length) {
    for (const batchItem of batchItems) jobs.push(batchItem);
  } else if (json.fileUrl || Object.prototype.hasOwnProperty.call(json, 'contentText')) {
    jobs.push(json);
  }
}

if (!jobs.length) {
  throw new Error('No download jobs found. Provide fileUrl/contentText or batchItems.');
}

concurrency = Math.max(1, Math.min(16, Math.floor(concurrency || 8)));
const normalizedJobs = jobs.map((job, index) => normalizeJob(job, index));

const rootFolder = normalizedJobs.find((job) => job.fileName === 'manifest.json' || job.fileName === 'prompts.json')?.folderPath || normalizedJobs[0].folderPath;
const requestedSupportFolder = clean(inputItems.find((item) => item.json?.supportFolderPath)?.json?.supportFolderPath || normalizedJobs.find((job) => job.supportFolderPath)?.supportFolderPath);
const tempRoot = requestedSupportFolder ? cleanFolderPath(requestedSupportFolder) : rootFolder;
const token = `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
const jobsFilePath = `${tempRoot}/s001-download-${token}-jobs.json`;
const scriptFilePath = `${tempRoot}/s001-download-${token}.js`;
const resultsFilePath = `${tempRoot}/s001-download-${token}-results.json`;

const downloaderScript = String.raw`
const fs = require('fs');
const path = require('path');
const http = require('http');
const https = require('https');

function normalizePath(value) {
  return String(value || '').replace(/\\/g, '/');
}

function ensureParent(filePath) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
}

function makeFailure(error, extra) {
  return { ok: false, error: error && error.message ? error.message : String(error), ...(extra || {}) };
}

function download(url, filePath, redirectCount = 0) {
  return new Promise((resolve, reject) => {
    if (!url) return reject(new Error('Missing fileUrl'));
    const client = /^https:/i.test(url) ? https : http;
    const req = client.get(url, { headers: { 'User-Agent': 'Mozilla/5.0 n8n-s001-batch-downloader' } }, (res) => {
      const statusCode = res.statusCode || 0;
      const location = res.headers.location;
      if ([301, 302, 303, 307, 308].includes(statusCode) && location && redirectCount < 5) {
        res.resume();
        const nextUrl = new URL(location, url).toString();
        resolve(download(nextUrl, filePath, redirectCount + 1));
        return;
      }
      if (statusCode < 200 || statusCode >= 300) {
        const chunks = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => reject(new Error('HTTP ' + statusCode + ': ' + Buffer.concat(chunks).toString('utf8').slice(0, 300))));
        res.on('error', reject);
        return;
      }
      ensureParent(filePath);
      const out = fs.createWriteStream(filePath);
      res.pipe(out);
      res.on('error', reject);
      out.on('finish', () => out.close(() => resolve({ statusCode })));
      out.on('error', reject);
    });
    req.setTimeout(120000, () => req.destroy(new Error('Download timeout after 120000ms')));
    req.on('error', reject);
  });
}

async function runJob(job, index) {
  const startedAt = Date.now();
  const filePath = normalizePath(job.localPath || job.savedPath || ((job.folderPath || '') + '/' + (job.fileName || '')));
  try {
    if (!filePath) throw new Error('Missing savedPath/localPath');
    if (job.fileUrl) {
      await download(job.fileUrl, filePath, 0);
      return { ok: true, index, type: job.type || 'image', fileKind: job.fileKind || 'image', fileName: job.fileName || path.basename(filePath), savedPath: filePath, sourceUrl: job.fileUrl, mimeType: job.mimeType || '', durationMs: Date.now() - startedAt };
    }
    ensureParent(filePath);
    fs.writeFileSync(filePath, String(job.contentText ?? ''), 'utf8');
    return { ok: true, index, type: job.type || 'text', fileKind: job.fileKind || 'text', fileName: job.fileName || path.basename(filePath), savedPath: filePath, sourceUrl: '', mimeType: job.mimeType || 'text/plain; charset=utf-8', durationMs: Date.now() - startedAt };
  } catch (error) {
    return makeFailure(error, { index, type: job.type || '', fileKind: job.fileKind || '', fileName: job.fileName || '', savedPath: filePath, sourceUrl: job.fileUrl || '', mimeType: job.mimeType || '', durationMs: Date.now() - startedAt });
  }
}

function cleanupFiles(paths) {
  for (const filePath of paths || []) {
    try {
      fs.unlinkSync(normalizePath(filePath));
    } catch (error) {}
  }
}

async function main() {
  const jobsPath = process.argv[2];
  const concurrencyArg = Number(process.argv[3] || '8');
  const payload = JSON.parse(fs.readFileSync(jobsPath, 'utf8'));
  const jobs = Array.isArray(payload.jobs) ? payload.jobs : [];
  const concurrency = Math.max(1, Math.min(16, Math.floor(concurrencyArg || payload.concurrency || 8)));
  const resultsPath = normalizePath(payload.resultsFilePath || jobsPath.replace(/-jobs\.json$/, '-results.json'));
  const results = new Array(jobs.length);
  let nextIndex = 0;

  async function worker() {
    while (nextIndex < jobs.length) {
      const index = nextIndex++;
      results[index] = await runJob(jobs[index], index);
    }
  }

  await Promise.all(Array.from({ length: Math.min(concurrency, Math.max(jobs.length, 1)) }, () => worker()));
  const summary = {
    ok: results.every((item) => item && item.ok),
    total: results.length,
    success: results.filter((item) => item && item.ok).length,
    failed: results.filter((item) => !item || !item.ok).length,
    concurrency,
    resultsPath,
    results,
  };
  ensureParent(resultsPath);
  fs.writeFileSync(resultsPath, JSON.stringify(summary, null, 2), 'utf8');
  console.log(JSON.stringify(summary));
  cleanupFiles(payload.cleanupFilePaths);
}

main().catch((error) => {
  const summary = { ok: false, total: 0, success: 0, failed: 1, concurrency: 0, results: [makeFailure(error, { fileKind: '', fileName: '', savedPath: '', sourceUrl: '' })] };
  console.log(JSON.stringify(summary));
});
`;

const cleanupFilePaths = [jobsFilePath, scriptFilePath, resultsFilePath];
const jobsPayload = JSON.stringify({ createdAt: new Date().toISOString(), concurrency, resultsFilePath, cleanupFilePaths, jobs: normalizedJobs }, null, 2);

function binaryItem(filePath, content, fileName, fileExtension) {
  return {
    json: {
      supportFilePath: filePath,
      jobsFilePath,
      scriptFilePath,
      resultsFilePath,
      concurrency,
      totalJobs: normalizedJobs.length,
      fileName,
    },
    binary: {
      data: {
        data: Buffer.from(content, 'utf8').toString('base64'),
        mimeType: 'text/plain; charset=utf-8',
        fileName,
        fileExtension,
      },
    },
  };
}

return [
  binaryItem(jobsFilePath, jobsPayload, 'download-jobs.json', 'json'),
  binaryItem(scriptFilePath, downloaderScript, 's001-batch-downloader.js', 'js'),
];

