const normalized = $('Normalize Batch Input').first().json;
const command = __buildNodeCommand([normalized.scriptFilePath, normalized.jobsFilePath, String(normalized.concurrency)]);

return [{
  json: {
    ok: true,
    command,
    jobsFilePath: normalized.jobsFilePath,
    scriptFilePath: normalized.scriptFilePath,
    resultsFilePath: normalized.resultsFilePath,
    concurrency: normalized.concurrency,
    totalJobs: normalized.totalJobs,
  },
}];

const run = $input.first().json || {};
const stdout = String(run.stdout || '').trim();
const stderr = String(run.stderr || '').trim();

function parseSummary(value) {
  const lines = value.split(/\r?\n/).map((line) => line.trim()).filter(Boolean).reverse();
  for (const line of lines) {
    try {
      const parsed = JSON.parse(line);
      if (parsed && typeof parsed === 'object') return parsed;
    } catch (error) {}
  }
  return null;
}

const summary = parseSummary(stdout);
if (!summary || !Array.isArray(summary.results)) {
  return [{
    json: {
      ok: false,
      fileKind: '',
      fileName: '',
      savedPath: '',
      sourceUrl: '',
      mimeType: '',
      error: `Batch downloader did not return valid JSON. stderr=${stderr.slice(0, 500)} stdout=${stdout.slice(0, 500)}`,
    },
  }];
}

return summary.results.map((result) => ({
  json: {
    ok: result.ok === true,
    fileKind: result.fileKind || result.type || '',
    fileType: result.fileKind || result.type || '',
    fileName: result.fileName || '',
    finalFileName: result.fileName || '',
    savedPath: result.savedPath || '',
    sourceUrl: result.sourceUrl || '',
    mimeType: result.mimeType || '',
    durationMs: result.durationMs || 0,
    error: result.error || '',
    batchTotal: summary.total || summary.results.length,
    batchSuccess: summary.success || 0,
    batchFailed: summary.failed || 0,
    concurrency: summary.concurrency || 0,
  },
}));
